INSERT INTO public.profile (id, name, title, tagline, email, location, bio, birthday_date, birthday_age, social_github, social_facebook, social_linkedin, social_instagram, accepting_projects) VALUES
(1, 'Anayatul Ahad Shoikot', 'FrontEnd Dev - ReactJs . NextJs . Framer . Webflow', 'Building digital experiences that push boundaries', 'shoikotofficial@gmail.com', 'Dhaka, Bangladesh', 'I''m a Computer-Science graduate & passionate about software - web development, with solid full-stack experience in PHP, JavaScript, and HTML/CSS. Currently, I''m leading the GradeSaver platform and working as a front-end developer. I am focused on JavaScript based frameworks like React.Js, Next.Js & Vue.Js to build interactive, responsive, user-friendly applications. I''m eager to grow through both full-time roles and freelance projects while continuing to sharpen my front-end expertise.', '30 November, 2000', 25, 'https://github.com/Anayatul-Ahad-Shoikot', 'https://www.facebook.com/ahadshoikot', 'https://www.linkedin.com/in/anayatul-ahad-shoikot', 'https://www.instagram.com/__shoi____kot__', true)
INSERT INTO public.projects (id, title, slug, description, images, tags, github, live, featured, year, category, sort_order) VALUES
(1, 'GradeSaver', 'gradesaver', 'GradeSaver is an online learning platform built to make education accessible and organized for students, mentors, and admins. Students can browse courses, enroll via bKash, attend classes, and access study materials through a simple, secure dashboard. Mentors get a separate panel to manage courses, upload class resources, and track student activity. A robust admin panel oversees all users, courses, batches, payments, and platform data. With role-based access, secure authentication, and smooth content management, GradeSaver provides a streamlined and efficient learning experience.', ARRAY['/assets/gradesaver-1.png', '/assets/gradesaver-2.png', '/assets/gradesaver-3.png', '/assets/gradesaver-4.png']::text[], ARRAY['HTML', 'CSS', 'JavaScript', 'Bootstrap', 'PHP', 'MySQL', 'Laragon', 'PHP Mailer', 'Box Icons']::text[], 'https://github.com/Anayatul-Ahad-Shoikot/GradeSaver', 'https://gradesaverbd.netlify.app/', false, '2024', 'Web App', 1),
(2, 'Crypgo', 'crypgo', 'A sleek, fully-responsive landing page for a modern cryptocurrency exchange. This landing page was an assessment and built in under 2 hours from scratch Figma design to real website.', ARRAY['/assets/crypgo-1.png', '/assets/crypgo-2.png', '/assets/crypgo-3.png', '/assets/crypgo-4.png']::text[], ARRAY['HTML', 'CSS', 'JavaScript', 'TailwindCSS', 'Google Fonts', 'Box Icons']::text[], 'https://github.com/Anayatul-Ahad-Shoikot/CrypGo', 'https://anayatul-ahad-shoikot.github.io/CrypGo/', false, '2025', 'Landing Page', 2),
(3, 'The DivineGroup Mumbai', 'the-divinegroup-mumbai', 'A Framer-built website for The DivineGroup Mumbai, highlighting events, nightlife experiences, and bold visual branding. Entire design and development done by me.', ARRAY['/assets/divine-1.png', '/assets/divine-2.png', '/assets/divine-3.png']::text[], ARRAY['Framer', 'Framer Motion']::text[], '#', 'https://www.divinegroupmumbai.com/', false, '2025', 'Landing Page', 3),
(4, 'Alex - AI', 'alex-ai', 'A clean, modern Framer-built landing page for Alex, a strategic AI-powered advisor designed to support business leaders, portfolio managers, and board directors. The site introduces Alex as an “executive team you can''t afford,” highlighting how it augments leadership with institutional intelligence, proactive insights, and continuous learning—positioning the tool as a smarter alternative to generic chat AI for high-level decision-making. It also features clear navigation with prompts to try the advisor, view pricing, and get in touch.', ARRAY['/assets/alex-1.png', '/assets/alex-2.png', '/assets/alex-3.png', '/assets/alex-4.png', '/assets/alex-5.png']::text[], ARRAY['Framer', 'Framer Motion', 'TypeScript']::text[], '#', 'https://alexaii.framer.website/', false, '2025', 'Web App', 4),
(5, 'IBTechPrep', 'ibtechprep', 'A professional Framer-built landing site for IBTechPrep, a curated platform offering the latest 2026 investment banking technical and behavioral interview questions, sourced directly from real firm recruiting cycles. The site highlights unique value by focusing on up-to-date interview content, structured question banks, and features designed to help candidates prepare more effectively than generic resources. It also includes clear navigation to pricing, FAQs, and access to the question bank — all presented with clean typography and a recruitment-focused design.', ARRAY['/assets/IBTechPrep-1.png', '/assets/IBTechPrep-2.png', '/assets/IBTechPrep-3.png', '/assets/IBTechPrep-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'TypeScript', 'Framer Auth']::text[], '#', 'https://ibtechprep.framer.website/', false, '2026', 'Web App', 5),
(6, 'Affi & Allie', 'affi-allie', 'A professional Framer-built landing site for Affi & Allié, a specialist affiliate marketing agency focused on helping DTC wellness brands scale through strategic partnerships and performance-driven campaigns. The site clearly communicates core services — including affiliate growth & optimization, premium program setup, performance audits, automation training, and custom solutions — alongside the agency’s data-led, results-first approach to influencer and performance marketing. The design emphasizes clarity, structured service breakdowns, and conversion-focused calls to action to engage prospective clients.', ARRAY['/assets/affiallie-1.png', '/assets/affiallie-2.png', '/assets/affiallie-3.png', '/assets/affiallie-4.png']::text[], ARRAY['Framer', 'Framer Motion']::text[], '#', 'https://affieallie.framer.website/', false, '2025', 'Landing Page', 6),
(7, 'Emotions', 'emotions', 'Emotions an emotional based dynamic studio platform where we host, create, brand your own programme.', ARRAY['/assets/emo-1.png', '/assets/emo-2.png', '/assets/emo-3.png', '/assets/emo-4.png']::text[], ARRAY['Framer', 'Framer Motion']::text[], '#', 'https://emotionss.framer.website/', false, '2025', 'Landing Page', 7),
(8, 'Nido Isola', 'nido-isola', 'NIDO ISOLA is a small, architect-designed holiday home on an exceptionally small hillside plot — created with the belief that true luxury is not about size, but about clarity. On Monte Isola, the largest lake island in Italy, we designed a boutique retreat where architecture, silence and light come together in a way that feels both intimate and expansive.', ARRAY['/assets/nido-1.png', '/assets/nido-2.png', '/assets/nido-3.png', '/assets/nido-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'Framer CMS', 'Tally Forms']::text[], '#', 'https://www.nidoisola.com/', false, '2025', 'Landing Page', 8),
(9, 'Book Yolo', 'book-yolo', 'BookYolo is an AI-powered travel tool designed to help you inspect the quality of hotels and vacation rentals before you actually book them. From vacation rentals to hotels, resorts, hostels, and even motels, BookYolo covers every kind of stay.', ARRAY['/assets/bookyolo-1.png', '/assets/bookyolo-2.png', '/assets/bookyolo-3.png', '/assets/bookyolo-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'Framer CMS', 'Tally Forms']::text[], '#', 'https://bookyolo.com/', false, '2025', 'Landing Page', 9),
(10, 'United One Communications', 'united-one-communications', 'United One Communications is a technology solutions provider delivering secure, innovative, and mission-focused capabilities to government and commercial organizations. Ensure mission-critical operations stay protected with advanced security engineered for the highest stakes.', ARRAY['/assets/uoc-1.png', '/assets/uoc-2.png', '/assets/uoc-3.png', '/assets/uoc-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'Framer CMS']::text[], '#', 'https://uoc.framer.website/', false, '2025', 'Landing Page', 10),
(11, 'Laser Me ( v1 )', 'laser-me-v1', 'A Framer-built landing page for LaserMee, a platform that helps users discover and promote events and nightlife experiences. This version highlights event browsing, community interaction, and bold visual branding. (This is the older version — the newer live version is available in another project.)', ARRAY['/assets/laser-1.png', '/assets/laser-2.png', '/assets/laser-3.png', '/assets/laser-4.png', '/assets/laser-5.png', '/assets/laser-6.png']::text[], ARRAY['Framer', 'Framer Motion', 'Google Analytics', 'HubSpot', 'MS Clarity', 'Hey Flow']::text[], '#', 'https://lasermee.framer.website/', false, '2025', 'Landing Page', 11),
(19, 'Kardiologicum (Parent company)', 'kardiologicum-parent-company', 'Spezialisten für Herzrhythmusstörungen, Telemonitoring und präventive Kardiologie in Neusäß & Augsburg. Moderne Diagnostik, kurze Wartezeiten, Top-Bewertungen.', ARRAY['/assets/kar2-1.png', '/assets/kar2-2.png', '/assets/kar2-3.png', '/assets/kar2-4.png']::text[], ARRAY['Framer', 'Framer Motion']::text[], '#', 'https://karrierekardiologicum.onepage.me', false, '2025', 'Landing Page', 12),
(12, 'Laser Me ( v2 )', 'laser-me-v2', 'A Framer-built landing page for LaserMee, a platform that helps users discover and promote events and nightlife experiences. This version highlights event browsing, community interaction, and bold visual branding. New and redesigned version. Entire design and development is done by me.', ARRAY['/assets/laser2-1.png', '/assets/laser2-2.png', '/assets/laser2-3.png']::text[], ARRAY['Framer', 'Framer Motion', 'Google Analytics', 'HubSpot', 'MS Clarity', 'Hey Flow']::text[], '#', 'https://laser.me/', false, '2026', 'Landing Page', 13),
(13, 'DPP Connects', 'dpp-connects', 'DPP Connect supports pharmacists on their Independent Prescribing (IP) journey by providing access to verified DPP mentors, structured supervision, and end-to-end placement support across the UK healthcare system. This Framer-built site was developed from a template called ''Healix'' and modified, redesigned heavily by me to align with the brand identity and user experience. I had to redesign and bring new sections, pages and interactions to keep up with the brand service.', ARRAY['/assets/dpp-1.png', '/assets/dpp-2.png', '/assets/dpp-3.png']::text[], ARRAY['Framer', 'Framer Motion', 'Google Analytics', 'Framer CMS']::text[], '#', 'https://www.dppconnect.co.uk', false, '2026', 'Landing Page', 14),
(14, 'Kardiologicum Augsburg & Neusass', 'kardiologicum-augsburg-neusass', 'Performance PLUS ist das kardiologische Premium-Programm für Menschen, die ihre Leistungsfähigkeit nicht schätzen, sondern fundiert verstehen wollen, damit Training, Gesundheit und Belastbarkeit endlich zusammenpassen.', ARRAY['/assets/cardio-1.png', '/assets/cardio-2.png', '/assets/cardio-3.png', '/assets/cardio-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'Framer CMS']::text[], '#', 'https://performanceplus.framer.website/', false, '2026', 'Landing Page', 15),
(15, 'Sore', 'sore', 'A premium Gym rebuilding project for sore, a high-end fitness center. This webflow-built site was developed from scratch and designed by me and my foreign partner. Client was so nice and co-operative. I had to redesign and bring new sections, pages and interactions to cope up with the brand service. Also I need to apply custom code for some functionality and interactions. ( Work in progress )', ARRAY['/assets/sore-1.png', '/assets/sore-2.png', '/assets/sore-3.png', '/assets/sore-4.png']::text[], ARRAY['Webflow', 'Webflow CMS', 'Webflow Form', 'Custom Code']::text[], '#', 'https://ersteinweisung.sore-health-club.com/', false, '2026', 'Landing Page', 16),
(16, 'Verdira', 'verdira', 'Verdira acquires ophthalmology practices from retiring physicians in NY, NJ, and CT. Physician ownership, permanent hold, no private equity. Your staff, name, and patients stay intact.', ARRAY['/assets/verdira-1.png', '/assets/verdira-2.png', '/assets/verdira-3.png', '/assets/verdira-4.png']::text[], ARRAY['Framer', 'Framer Motion', 'Framer CMS', 'Custom Code']::text[], '#', 'https://www.verdira.com/', false, '2026', 'Web App', 17),
(17, 'Intellix Solutions LTD', 'intellix-solutions-ltd', 'Intellix — Software Development, BPO & Technology Solutions from Bangladesh.', ARRAY['/assets/intellix-1.png', '/assets/intellix-2.png', '/assets/intellix-3.png']::text[], ARRAY['Next.js', 'Framer Motion', 'TailwindCSS', 'React']::text[], 'https://github.com/intellixAhad/Intellix', 'https://www.intellixsolutions.co/', true, '2026', 'Website', 18),
(18, 'CareOps', 'careops', 'Remote administrative support for US medical practices and home care agencies.', ARRAY['/assets/careops-1.png', '/assets/careops-2.png', '/assets/careops-3.png']::text[], ARRAY['Next.js', 'Framer Motion', 'TailwindCSS', 'React', 'Radix UI']::text[], 'https://github.com/intellixAhad/CareOps', 'https://www.thecareops.com/', true, '2026', 'Landing Page', 19)
INSERT INTO public.experiences (role, company, period, description, sort_order) VALUES
('Freelancer - Web Development', 'Upwork', 'May 2026 - Present', 'Project hunting, foreign client communication, understanding client vision, UI/UX design, site development (Framer, Webflow)', 1),
('Framer Developer & Analytics Specialist', 'Contract Based', 'Dec 2025 — Present', 'Developing the website from the ground up, analyzing user behavior and traffic patterns, and implementing strategic design and content improvements to enhance engagement and reach. ( Framer, webflow )', 2),
('Frontend Developer (Framer & Webflow)', 'Softvence', 'Sep 2025 — Jan 2026', 'Focused on Webflow and Framer development, delivering structured design systems, GSAP interactions, 3D animation workflows, and fully responsive interfaces. Collaborated closely on project management and client communication.', 3),
('Junior Web Developer (Intern)', 'Business Automation LTD', 'Jul 2024 — Sep 2024', 'Worked with Laravel Blade templates, UI styling, session and cookie management, REST API testing using Postman, ORM modeling, and foundational React development.', 4),
('HR Intern', 'GAOTek Inc.', 'Jun 2025 — Aug 2025', 'Assisted with HR operations, candidate screening, communication handling, and administrative support while gaining hands-on experience in HR processes and organizational management.', 5),
('Grader', 'United International University', '2023 — 2024', 'Evaluated student assignments and lab reports, provided academic support, and assisted faculty members with course-related documentation and administrative tasks.', 6),
('Treasurer', 'UIU Computer Club', 'Jan 2024 — Oct 2024', 'Oversaw budgeting, managed the registration and HR processes, coordinated with multiple departments, and supported event and operational planning.', 7),
('Peer Mentor', 'UIU Computer Club', 'Dec 2022 — Nov 2024', 'Guided junior students in programming and core academic courses including SPL, OOP, DLD, Physics, and Calculus. Provided structured learning support and study guidance.', 8),
('Senior HR Executive', 'UIU Computer Club', '2022 — 2024', 'Managed a member base of over 2,000, organized technical events and recruitment processes, supervised registration operations, and developed FAQ and onboarding guidance for members.', 9),
('Junior HR Executive', 'UIU Computer Club', '2021 — 2022', 'Handled member registration, onboarding communication, and recruitment activities while actively contributing to club events as a volunteer.', 10);
